'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );
var axis = require( './axis.js' );


// MAIN //

/**
* Adds an axes menu to an editor.
*
* @private
* @param {Editor} editor - editor instance
* @param {Array<Object>} conf - list of editor axis configurations
* @param {Object} schema - visualization schema
* @returns {(Object|null)} menu tree
*/
function addMenu( editor, conf, schema ) {
	var children;
	var folder;
	var o;
	var i;

	if ( conf.length === 0 ) {
		return null;
	}
	folder = editor.addFolder( 'Axes' );
	folder.close();

	children = [];
	for ( i = 0; i < conf.length; i++ ) {
		o = axis( folder, conf[ i ], schema, format( 'Axis %d', i+1 ) );
		if ( o ) {
			children.push( o );
		}
	}
	return {
		'folder': folder,
		'children': children
	};
}


// EXPORTS //

module.exports = addMenu;
